// The frame a part of the pane sits in: a top border that carries a title on the left and a few words
// on the right, side borders around the content, a bottom border. Every line is exactly `width` columns.

import { FRAME, pick } from './glyphs'
import { QUIET, S } from './style'
import type { Line, Span } from './spans'
import { barLine, lineWidth, padSpans, truncateSpans } from './spans'

/** Columns the borders and the blank beside them take from the content of a framed row. */
export const FRAME_COLUMNS = 4

/** The columns of content a frame `width` wide holds. */
export function frameInner(width: number): number {
  return Math.max(1, width - FRAME_COLUMNS)
}

/**
 * `╭─ Details ────────────── ✓ adopted  model  10-01 ─╮`: the title (kept before anything else), the
 * right-hand words (given up when there is no room for them), and the border between.
 */
export function frameTop(width: number, o: { title: readonly Span[]; right?: readonly Span[]; ascii: boolean }): Line {
  const h = pick(FRAME.h, o.ascii)
  const corner = (c: string): Span => S(c, QUIET)
  const bar = (n: number): Span => S(h.repeat(Math.max(0, n)), QUIET)
  const title: Line = o.title.length === 0 ? [] : [S(' '), ...o.title, S(' ')]
  const right: Line = o.right === undefined || o.right.length === 0 ? [] : [S(' '), ...o.right, S(' ')]
  // corner, one dash, title, dashes, right, one dash, corner
  const fixed = 2 + 2
  const room = width - fixed
  let t = title
  let r = right
  if (lineWidth(t) + lineWidth(r) + 1 > room) r = []
  if (lineWidth(t) > room) t = truncateSpans(t, room)
  const fill = room - lineWidth(t) - lineWidth(r)
  return [corner(pick(FRAME.tl, o.ascii)), bar(1), ...t, bar(fill), ...r, bar(1), corner(pick(FRAME.tr, o.ascii))]
}

/** `│ content          │`, the content cut or padded to the width inside. */
export function frameRow(content: readonly Span[], width: number, ascii: boolean): Line {
  const v = S(pick(FRAME.v, ascii), QUIET)
  return [v, S(' '), ...padSpans(content, frameInner(width)), S(' '), v]
}

/** `│▌content░░░░░░░░░░░│`: a row of the frame with a band behind it and a bar in the first column inside, for the row picked in a list. */
export function frameBand(content: readonly Span[], width: number, ascii: boolean, o: { bg: string; bar: string; barColor: string }): Line {
  const v = S(pick(FRAME.v, ascii), QUIET)
  return [v, S(o.bar, { color: o.barColor, bg: o.bg }), ...barLine(padSpans(content, frameInner(width)), o.bg, frameInner(width)), S(' ', { bg: o.bg }), v]
}

/** `│                  │`. */
export function frameBlank(width: number, ascii: boolean): Line {
  return frameRow([], width, ascii)
}

/** The border at the bottom. */
export function frameBottom(width: number, ascii: boolean): Line {
  const h = pick(FRAME.h, ascii)
  return [S(pick(FRAME.bl, ascii), QUIET), S(h.repeat(Math.max(0, width - 2)), QUIET), S(pick(FRAME.br, ascii), QUIET)]
}

/** The two borders' columns on the left and the right of a row, for a part that draws its own content between them (a button). */
export function frameSides(width: number, contentWidth: number, ascii: boolean): { left: Line; right: Line } {
  const v = S(pick(FRAME.v, ascii), QUIET)
  const pad = Math.max(0, frameInner(width) - contentWidth)
  return { left: [v, S(' ')], right: [S(' '.repeat(pad + 1)), v] }
}

files.lib/foot.ts:
// The keys at the bottom of the pane. Each is a button whose hotkey works while the pane holds the focus,
// so a key that is not drawn does not work: when the pane is narrow the least useful ones go first.
//
//   k: ↑  j: ↓  ⏎: expand  e: edit  p: pending  t: trees  o: next tree  c: colors      warnings 2  l: 中
//   k: ↑  j: ↓  ⏎: open  r: record here  n: new tree  t: back                                    l: 中     (the overview)
//   k: ↑  j: ↓  ⏎: use  r: default  c: back                                                      l: 中     (the colours)
//
// The engine draws a hotkey button without chrome, as `key: label` (the key in the accent colour); that
// is why the hints read like this and are not key caps.

import type { DtFilter, DtLang } from '../types'
import type { Part } from './bar'
import { buttonPart, partWidth, partsWidth, textPart } from './bar'
import { t } from './i18n'
import { QUIET, S } from './style'

/** The columns between two keys. */
export const GAP = 2

/** What the bottom of the tree view depends on. */
export type FooterInput = {
  lang: DtLang
  ascii: boolean
  /** The pane has a text field to edit in, and shows the tree that is recorded into. */
  canEdit: boolean
  filter: DtFilter
  hasNow: boolean
  showNow: boolean
  /** How many trees the project has. */
  trees: number
  warnings: number
}

export type FooterItems = {
  /** The keys, most useful first. */
  items: Part[]
  /** The part flush right: the count of warnings, and the language key (never dropped). */
  right: Part[]
}

/** `l: 中` in an English pane, `l: EN` in a Chinese one: the key names the language it switches to. */
export function languageKey(lang: DtLang): Part {
  const to: DtLang = lang === 'zh' ? 'en' : 'zh'
  return buttonPart('~lang', { do: 'lang', lang: to }, [S(to === 'en' ? 'EN' : '中')], { hotkey: 'l' })
}

export function warningsPart(lang: DtLang, count: number): Part {
  return buttonPart('~warnings', { do: 'warnings' }, count > 0 ? [S(t(lang, 'pane.warnings', { n: count }), { color: 'warning' })] : [S(t(lang, 'pane.warnings', { n: count }))], { dim: count === 0 })
}

function key(id: string, hotkey: string, label: string, action: Parameters<typeof buttonPart>[1], active = false): Part {
  return buttonPart(`~${id}`, action, [S(label, active ? { bold: true } : {})], { hotkey })
}

/** The hint for Enter, which is the press of the focused row and so needs no button of its own. */
export function enterHint(lang: DtLang, ascii: boolean, label = t(lang, 'key.expand')): Part {
  return textPart([S(`${ascii ? 'Enter' : '⏎'}: ${label}`, QUIET)])
}

/** What the bottom of the overview depends on. */
export type OverviewKeysInput = {
  lang: DtLang
  ascii: boolean
  /** The pane has text fields to name a new tree in. */
  canCreate: boolean
  /** The form for a new tree is open. */
  forming: boolean
}

/** The keys of the overview, most useful first; while the form for a new tree is open, the one that makes it. */
export function overviewItems(f: OverviewKeysInput): FooterItems {
  const right: Part[] = [languageKey(f.lang)]
  if (f.forming) return { items: [enterHint(f.lang, f.ascii, t(f.lang, 'key.create'))], right }
  const items: Part[] = [
    key('up', 'k', f.ascii ? 'up' : '↑', { do: 'move', by: -1 }),
    key('down', 'j', f.ascii ? 'down' : '↓', { do: 'move', by: 1 }),
    enterHint(f.lang, f.ascii, t(f.lang, 'key.open')),
    key('record', 'r', t(f.lang, 'key.record'), { do: 'record' }),
  ]
  if (f.canCreate) items.push(key('new', 'n', t(f.lang, 'key.new'), { do: 'new' }))
  items.push(key('back', 't', t(f.lang, 'key.back'), { do: 'back' }))
  return { items, right }
}

/** What the bottom of the picker of colours depends on. */
export type PickerKeysInput = {
  lang: DtLang
  ascii: boolean
}

/** The keys of the picker of colours. `⏎: use` is a button too, so that a click can keep the scheme that is highlighted. */
export function pickerItems(f: PickerKeysInput): FooterItems {
  const items: Part[] = [
    key('up', 'k', f.ascii ? 'up' : '↑', { do: 'move', by: -1 }),
    key('down', 'j', f.ascii ? 'down' : '↓', { do: 'move', by: 1 }),
    buttonPart('~use', { do: 'use' }, [S(`${f.ascii ? 'Enter' : '⏎'}: ${t(f.lang, 'key.use')}`, QUIET)]),
    key('reset', 'r', t(f.lang, 'colors.default'), { do: 'reset' }),
    key('back', 'c', t(f.lang, 'key.back'), { do: 'back' }),
  ]
  return { items, right: [languageKey(f.lang)] }
}

/** The keys of the tree view, most useful first. */
export function footerItems(f: FooterInput): FooterItems {
  const items: Part[] = [
    key('up', 'k', f.ascii ? 'up' : '↑', { do: 'move', by: -1 }),
    key('down', 'j', f.ascii ? 'down' : '↓', { do: 'move', by: 1 }),
    enterHint(f.lang, f.ascii),
  ]
  if (f.canEdit) items.push(key('edit', 'e', t(f.lang, 'key.edit'), { do: 'edit' }))
  items.push(key('pending', 'p', t(f.lang, 'key.pending'), { do: 'filter', filter: 'pending' }, f.filter === 'pending'))
  items.push(key('trees', 't', t(f.lang, 'key.trees'), { do: 'overview' }))
  if (f.trees > 1) items.push(key('cycle', 'o', t(f.lang, 'key.tree'), { do: 'cycle', by: 1 }))
  items.push(key('colors', 'c', t(f.lang, 'key.colors'), { do: 'colors' }))
  items.push(key('clean', 'h', t(f.lang, 'key.clean'), { do: 'filter', filter: 'clean' }, f.filter === 'clean'))
  items.push(key('all', 'a', t(f.lang, 'key.all'), { do: 'filter', filter: 'all' }, f.filter === 'all'))
  if (f.hasNow) items.push(key('now', 's', t(f.lang, 'key.now'), { do: 'now' }, f.showNow))
  const right: Part[] = []
  if (f.warnings > 0) right.push(warningsPart(f.lang, f.warnings), textPart([S(' '.repeat(GAP))]))
  right.push(languageKey(f.lang))
  return { items, right }
}

/**
 * Packs the keys into at most `maxLines` lines of `width` columns. The right group (the warnings, the language
 * key) has first claim on the end of the first line; keys that do not fit are dropped from the end. Each line is
 * the parts to draw, the gaps and the padding between them included.
 */
export function packBar(items: readonly Part[], right: readonly Part[], width: number, maxLines: number): Part[][] {
  const gap = textPart([S(' '.repeat(GAP))])
  // narrow: the count of warnings goes first, then the right group altogether
  const groups = [right, right.filter(p => p.kind === 'button' && p.hotkey !== null), []]
  const keep = groups.find(g => g.length === 0 || width >= partsWidth(g) + 24) ?? []
  const reserve = keep.length > 0 ? partsWidth(keep) + GAP : 0

  const lines: Part[][] = [[]]
  let used = 0
  let limit = width - reserve
  for (const item of items) {
    const w = partWidth(item)
    const cur = lines[lines.length - 1]!
    const need = (cur.length > 0 ? GAP : 0) + w
    if (used + need <= limit) {
      if (cur.length > 0) cur.push(gap)
      cur.push(item)
      used += need
      continue
    }
    if (lines.length < maxLines && w <= width) {
      lines.push([item])
      used = w
      limit = width
    }
    // otherwise it fits nowhere and is left out
  }
  if (keep.length > 0) {
    const first = lines[0]!
    const pad = Math.max(1, width - partsWidth(first) - partsWidth(keep))
    first.push(textPart([S(' '.repeat(pad))]), ...keep)
  }
  return lines
}

files.lib/head.ts:
// The top of the pane: the strip (the project, one tab for each tree, the language switch), the line of
// state under it (how much there is, whether it is recording) and, for a tree that was opened from another,
// the line that says where it began.
//
//   notes-app   main ●   crdt-engine   cloud-first                        EN 中
//   9 decisions   mainline 5 steps                    ○ read only   recording in main   updated 15:28
//   ↳ main #5 (09-21)   CRDT text engine instead of paragraph merge

import type { DtForkBase, DtLang, DtMode } from '../types'
import type { Part } from './bar'
import { buttonPart, partWidth, partsWidth, textPart } from './bar'
import { fmtClock } from './events'
import { MARKS, glyphOf, laneColour, pick } from './glyphs'
import { richSpans } from './highlight'
import { decisionsText, mainlineText, t, treesText } from './i18n'
import { QUIET, S } from './style'
import type { Line, Span } from './spans'
import { fitSpans, lineWidth, truncateSpans } from './spans'
import { whenOfName } from './versions'
import { plain, strWidth, truncate } from './width'

// ---------------------------------------------------------------- the strip

export type HeaderInput = {
  /** Columns the strip may use. */
  width: number
  lang: DtLang
  ascii: boolean
  /** The project's name. */
  title: string
  /** The trees of the project in the order they are listed; fewer than two draw no tabs. */
  trees: readonly string[]
  /** The tree the pane shows. */
  viewed: string
  /** The tree the project records into, when it records. */
  recording: string | null
  /** How many texts wait for their rendition in the other language. */
  translating: number
}

/** The columns the project's name keeps at the least, however narrow the pane. */
const MIN_NAME = 6
const TAB_GAP = 3
const MAIN_GAP = 2
/** The columns the viewed tab keeps when it is alone, before the count of translations next to the switch gives way. */
const ALONE_MIN = 8

/** `EN 中`: the language in use is bold and underlined, the other one quiet; each is a button. */
export function languageToggle(lang: DtLang): Part[] {
  const one = (code: DtLang, label: string): Part => {
    const on = lang === code
    return buttonPart(`~lang-${code}`, { do: 'lang', lang: code }, [S(label, on ? { color: 'text', bold: true, underline: true } : { color: 'inactive', dim: true })])
  }
  return [one('en', 'EN'), textPart([S('  ')]), one('zh', '中')]
}

function tabPart(name: string, o: { viewed: boolean; recording: boolean; ascii: boolean; cut: number }): Part {
  const label = o.cut > 0 ? truncate(name, o.cut) : name
  const spans: Span[] = [S(label, o.viewed ? { color: 'text', bold: true, underline: true } : { color: 'inactive', dim: true })]
  if (o.recording) spans.push(S(' '), S(pick(MARKS.dot, o.ascii), { color: 'success' }))
  return buttonPart(`~tab-${name}`, { do: 'tab', tree: name }, spans)
}

/**
 * The tabs that fit in `room` columns, as parts (buttons with a gap between): every tab when they fit,
 * else every tab with its name cut shorter, else the viewed one with as many of its neighbours as fit
 * and a `…` where the others are. Null when not even the viewed one fits in `aloneMin` columns.
 */
function tabs(h: HeaderInput, room: number, aloneMin: number): Part[] | null {
  const tab = (name: string, cut: number): Part => tabPart(name, { viewed: name === h.viewed, recording: name === h.recording, ascii: h.ascii, cut })
  const build = (cut: number): Part[] => h.trees.map(name => tab(name, cut))
  const widthOf = (parts: readonly Part[]) => partsWidth(parts) + TAB_GAP * Math.max(0, parts.length - 1)
  for (const cut of [0, 16, 12, 8]) {
    const all = build(cut)
    if (widthOf(all) <= room) return withGaps(all)
  }
  const all = build(12)
  const at = Math.max(0, h.trees.indexOf(h.viewed))
  const mark = 1 + TAB_GAP // a `…` and its gap
  const cost = (a: number, b: number) => widthOf(all.slice(a, b + 1)) + (a > 0 ? mark : 0) + (b < all.length - 1 ? mark : 0)
  if (cost(at, at) > room) {
    // not even the viewed tab with its neighbours' marks: it alone, cut to what is there
    const name = h.trees[at]!
    const cut = room - (name === h.recording ? 2 : 0)
    return cut >= aloneMin ? [tab(name, cut)] : null
  }
  let lo = at
  let hi = at
  // grow the window around the viewed tab, the newer side first
  for (;;) {
    if (hi + 1 < all.length && cost(lo, hi + 1) <= room) hi += 1
    else if (lo > 0 && cost(lo - 1, hi) <= room) lo -= 1
    else break
  }
  const parts = withGaps(all.slice(lo, hi + 1))
  const more = textPart([S('…', QUIET)])
  if (lo > 0) parts.unshift(more, textPart([S(' '.repeat(TAB_GAP))]))
  if (hi < all.length - 1) parts.push(textPart([S(' '.repeat(TAB_GAP))]), more)
  return parts
}

function withGaps(parts: readonly Part[]): Part[] {
  const out: Part[] = []
  parts.forEach((p, k) => {
    if (k > 0) out.push(textPart([S(' '.repeat(TAB_GAP))]))
    out.push(p)
  })
  return out
}

/**
 * The strip, `h.width` columns across: the name in bold, the tabs after it, and on the right the count of
 * texts being translated and the language switch. The name has the first claim on the room (cut to under
 * half of the strip); the tabs get what is left, then give up their length, then their neighbours of the
 * viewed one; the count of translations goes before the switch does.
 */
export function headerBar(h: HeaderInput): Part[] {
  const toggle = languageToggle(h.lang)
  const busy =
    h.translating > 0
      ? textPart([S(`${glyphOf('proposed', h.ascii)} ${t(h.lang, 'pane.translating', { n: h.translating })}`, { color: 'suggestion' })])
      : null
  const rights: Part[][] = busy === null ? [toggle] : [[busy, textPart([S('   ')]), ...toggle], toggle]
  const name = plain(h.title)
  const nameCap = Math.max(MIN_NAME, Math.floor(h.width * 0.45))
  const hasTabs = h.trees.length > 1

  for (const [k, right] of rights.entries()) {
    const rightW = partsWidth(right)
    const room = h.width - rightW - MAIN_GAP
    // the name in full or cut, then the tabs in what is left
    const shown = truncate(name, Math.min(nameCap, Math.max(0, room)))
    const nameW = name === '' ? 0 : strWidth(shown)
    if (name !== '' && nameW < Math.min(strWidth(name), MIN_NAME)) continue
    const left: Part[] = name === '' ? [] : [textPart([S(shown, { bold: true })])]
    if (hasTabs) {
      // (the count of translations is given up before the viewed tab is cut to a stump)
      const shownTabs = tabs(h, room - nameW - (nameW > 0 ? TAB_GAP : 0), k < rights.length - 1 ? ALONE_MIN : 3)
      if (shownTabs === null && k < rights.length - 1) continue
      if (shownTabs !== null) {
        if (nameW > 0) left.push(textPart([S(' '.repeat(TAB_GAP))]))
        left.push(...shownTabs)
      }
    }
    const pad = Math.max(MAIN_GAP, h.width - partsWidth(left) - rightW)
    return [...left, textPart([S(' '.repeat(pad))]), ...right]
  }
  // nothing else fits: the switch alone
  const bare = truncate(name, Math.max(0, h.width - partsWidth(toggle) - MAIN_GAP))
  const pad = Math.max(1, h.width - strWidth(bare) - partsWidth(toggle))
  return [...(bare === '' ? [] : [textPart([S(bare, { bold: true })])]), textPart([S(' '.repeat(pad))]), ...toggle]
}

// ---------------------------------------------------------------- the line of state

export type StateInput = {
  width: number
  lang: DtLang
  ascii: boolean
  mode: Exclude<DtMode, 'off'>
  /** Decisions that are not retracted, and the steps of the mainline. */
  count: number
  steps: number
  lastEventAt: string | null
  /** The pane shows a tree that is not the one recorded into. */
  readOnly: boolean
  /** The tree recorded into. */
  recording: string
}

/**
 * `9 decisions   mainline 5 steps          ● recording   updated 15:28`: what there is on the left, quiet; on the
 * right whether it is being recorded, which gives up the clock, then the tree it is recorded into, then its word.
 */
export function stateLine(s: StateInput): Line {
  const dot = pick(MARKS.dot, s.ascii)
  const ring = s.ascii ? 'o' : '○'
  const paused = s.mode === 'paused'
  const live = (word: string): Line => [S(dot, { color: paused ? 'warning' : 'success' }), S(' '), S(word, paused ? { color: 'warning' } : { color: 'success' })]
  const clock = fmtClock(s.lastEventAt)
  const updated: Line = clock === '' ? [] : [S('   ' + t(s.lang, 'pane.updated', { time: clock }), QUIET)]
  const state: Line = s.readOnly ? [S(ring, { color: 'inactive' }), S(' '), S(t(s.lang, 'pane.state.readOnly'), { color: 'inactive' })] : live(t(s.lang, paused ? 'pane.state.paused' : 'pane.state.recording'))
  const where: Line = s.readOnly
    ? paused
      ? [S('   '), ...live(t(s.lang, 'pane.state.paused'))]
      : [S('   ' + t(s.lang, 'pane.recordingIn', { tree: plain(s.recording) }), { color: 'success', dim: true })]
    : []
  const options: Line[] = []
  if (updated.length > 0) options.push([...state, ...where, ...updated])
  options.push([...state, ...where], state, [state[0]!])

  const full: Line = [S(decisionsText(s.lang, s.count), QUIET), S('   ', QUIET), S(mainlineText(s.lang, s.steps), QUIET)]
  const short: Line = [S(decisionsText(s.lang, s.count), QUIET)]
  for (const left of [full, short]) {
    for (const right of options) {
      if (lineWidth(left) + lineWidth(right) + MAIN_GAP <= s.width) return fitSpans(left, right, s.width, MAIN_GAP)
    }
  }
  return fitSpans(short, options[options.length - 1]!, s.width, MAIN_GAP)
}

/** The state line of the overview: how many trees there are, and whether the project is recording (and into which). */
export type OverviewStateInput = {
  width: number
  lang: DtLang
  ascii: boolean
  mode: Exclude<DtMode, 'off'>
  trees: number
  lastEventAt: string | null
  /** The tree recorded into. */
  recording: string
}

/** `3 trees          ● recording in main   updated 15:28`: the count on the left, the state on the right (the clock goes first when it is narrow). */
export function overviewStateLine(s: OverviewStateInput): Line {
  const dot = pick(MARKS.dot, s.ascii)
  const paused = s.mode === 'paused'
  const clock = fmtClock(s.lastEventAt)
  const head: Line = [S(dot, { color: paused ? 'warning' : 'success' }), S(' ')]
  const word = paused ? S(t(s.lang, 'pane.state.paused'), { color: 'warning' }) : S(t(s.lang, 'pane.recordingIn', { tree: plain(s.recording) }), { color: 'success' })
  const options: Line[] = []
  if (clock !== '') options.push([...head, word, S('   ' + t(s.lang, 'pane.updated', { time: clock }), QUIET)])
  options.push([...head, word])
  if (!paused) options.push([...head, S(t(s.lang, 'pane.state.recording'), { color: 'success' })])
  options.push([head[0]!])
  const left: Line = [S(treesText(s.lang, s.trees), QUIET)]
  for (const right of options) {
    if (lineWidth(left) + lineWidth(right) + MAIN_GAP <= s.width) return fitSpans(left, right, s.width, MAIN_GAP)
  }
  return fitSpans(left, options[options.length - 1]!, s.width, MAIN_GAP)
}

// ---------------------------------------------------------------- where a tree began

/**
 * `↳ main #5 (09-21)   CRDT text engine instead of paragraph merge`: the tree it was opened from, the version, the day
 * of it, and what the tree is for. `laneOf` gives the colour of a tree's lane; `mark` (`中` or `EN`) follows a title that
 * is still in the language it was written in because its rendition has not arrived.
 */
export function originLine(fork: DtForkBase & { title?: string }, o: { width: number; lang: DtLang; ascii: boolean; laneOf: (tree: string) => string; mark?: string | null }): Line {
  const line: Line = [S(o.ascii ? '>' : '↳', QUIET), S(' ')]
  if (fork.count === 0 || fork.at === null) {
    line.push(S(t(o.lang, 'tree.fromEmpty'), QUIET))
  } else {
    const day = whenOfName(fork.at).split(' ')[0] ?? ''
    line.push(S(plain(fork.tree), { color: o.laneOf(fork.tree) }), S(' '), S(`#${fork.count}`, { color: 'warning' }))
    if (day !== '') line.push(S(' '), S(`(${day})`, QUIET))
  }
  const title = fork.title === undefined ? '' : plain(fork.title)
  if (title !== '') {
    const mark = o.mark ?? null
    line.push(S('   '), ...(mark !== null ? [S(title, QUIET), S(' '), S(mark, QUIET)] : richSpans(title, { color: 'inactive', dim: true }, true)))
  }
  return truncateSpans(line, o.width)
}

